package sample

import (
	"bytes"
	"encoding/binary"

	"mediaproc/internal/ebml"
)

// Config controls deterministic fixture generation.
type Config struct {
	Seed  int64
	Fault string
}

// Fixture contains generated bytes and offsets tests should assert.
type Fixture struct {
	Data              []byte
	FaultOffset       int64
	RecoveryClusterMS int
	ClusterCount      int
	KeyframeCount     int
}

const clusterCount = 60 // 60 * 20 ms = 1200 ms, six 200 ms segments.

// Generate builds a small Matroska/WebM stream with unknown-length Segment
// and Cluster elements. Faults are injected at the 400 ms keyframe cluster.
func Generate(cfg Config) Fixture {
	if cfg.Seed == 0 {
		cfg.Seed = 41
	}
	var buf bytes.Buffer
	buf.Write(ebml.BuildElement(ebml.IDEBMLHeader, nil))
	buf.Write(ebml.UnknownHeader(ebml.IDSegment, 8))
	buf.Write(buildInfo())
	buf.Write(buildTracks())

	f := Fixture{RecoveryClusterMS: 420, ClusterCount: clusterCount, KeyframeCount: 6}
	for i := 0; i < clusterCount; i++ {
		tMS := i * 20
		buf.Write(ebml.UnknownHeader(ebml.IDCluster, 8))
		buf.Write(ebml.UintElement(ebml.IDTimecode, uint64(tMS)))

		if i%10 == 0 {
			writeVideoBlock(&buf, cfg, i, &f)
		}
		writeAudioBlock(&buf, cfg, i)
		if cfg.Fault == "missing-cluster-end" && i == 29 {
			f.ClusterCount = 30
			f.KeyframeCount = 3
			break
		}
	}
	f.Data = append([]byte(nil), buf.Bytes()...)
	return f
}

func buildInfo() []byte {
	payload := append([]byte(nil), ebml.UintElement(ebml.IDTimecodeScale, 1_000_000)...)
	payload = append(payload, ebml.StringElement(ebml.IDMuxingApp, "mediaproc-fixture")...)
	payload = append(payload, ebml.StringElement(ebml.IDWritingApp, "mediaproc")...)
	return ebml.BuildElement(ebml.IDInfo, payload)
}

func buildTracks() []byte {
	video := append([]byte(nil), ebml.UintElement(ebml.IDTrackNumber, 1)...)
	video = append(video, ebml.UintElement(ebml.IDTrackUID, 101)...)
	video = append(video, ebml.UintElement(ebml.IDTrackType, ebml.TrackTypeVideo)...)
	video = append(video, ebml.StringElement(ebml.IDCodecID, "V_MPEG4/ISO/AVC")...)
	videoEntry := ebml.BuildElement(ebml.IDTrackEntry, video)

	audioInfo := ebml.UintElement(ebml.IDChannels, 1)
	audio := append([]byte(nil), ebml.UintElement(ebml.IDTrackNumber, 2)...)
	audio = append(audio, ebml.UintElement(ebml.IDTrackUID, 202)...)
	audio = append(audio, ebml.UintElement(ebml.IDTrackType, ebml.TrackTypeAudio)...)
	audio = append(audio, ebml.StringElement(ebml.IDCodecID, "A_OPUS")...)
	audio = append(audio, ebml.BuildElement(ebml.IDAudio, audioInfo)...)
	audioEntry := ebml.BuildElement(ebml.IDTrackEntry, audio)

	return ebml.BuildElement(ebml.IDTracks, append(videoEntry, audioEntry...))
}

func blockPayload(track uint64, timecodeMS int16, flags byte, payload []byte) []byte {
	out := ebml.EncodeSize(track)
	var tc [2]byte
	binary.BigEndian.PutUint16(tc[:], uint16(timecodeMS))
	out = append(out, tc[0], tc[1], flags)
	return append(out, payload...)
}

func writeVideoBlock(buf *bytes.Buffer, cfg Config, cluster int, f *Fixture) {
	keyframePayload := []byte{0x00, 0x00, 0x00, 0x01, 0x67, byte(cluster), 0x0d, 0x0a}
	block := blockPayload(1, 0, 0x80, keyframePayload)

	if cluster == 20 && cfg.Fault == "bad-lacing" {
		f.FaultOffset = int64(buf.Len())
		// Keyframe + Xiph lacing, frame count six, but truncated size coding.
		bad := []byte{0x81, 0x00, 0x00, 0x82, 0x05, 0xff, 0xff, 0xff}
		buf.Write(ebml.BuildElement(ebml.IDSimpleBlock, bad))
		return
	}
	if cluster == 20 && cfg.Fault == "truncated-block" {
		f.FaultOffset = int64(buf.Len())
		buf.Write(ebml.ElementHeader(ebml.IDSimpleBlock, 2))
		buf.Write([]byte{0x81, 0x00})
		return
	}
	if cluster == 20 && cfg.Fault == "invalid-vint" {
		// The illegal zero size descriptor begins immediately after the ID.
		buf.Write(ebml.EncodeID(ebml.IDSimpleBlock))
		f.FaultOffset = int64(buf.Len())
		buf.WriteByte(0x00)
		_, _ = buf.Write([]byte{0x81, 0x00, 0x80})
		return
	}
	buf.Write(ebml.BuildElement(ebml.IDSimpleBlock, block))
}

func writeAudioBlock(buf *bytes.Buffer, cfg Config, cluster int) {
	var packet []byte
	switch {
	case cluster == 10:
		packet = SilencePacket()
	case cluster == 31:
		// Exact repeat of cluster 30, at a different timestamp.
		packet = DuplicateVoicePacket(cfg.Seed)
	default:
		packet = VoicePacket(cfg.Seed, cluster)
	}
	block := blockPayload(2, 0, 0x00, packet)
	buf.Write(ebml.BuildElement(ebml.IDSimpleBlock, block))
}

// GenerateUnsupportedAudio builds a tiny one-track audio stream with a codec
// for which no decoder is registered.
func GenerateUnsupportedAudio() []byte {
	var buf bytes.Buffer
	buf.Write(ebml.BuildElement(ebml.IDEBMLHeader, nil))
	buf.Write(ebml.UnknownHeader(ebml.IDSegment, 8))
	buf.Write(buildInfo())

	track := append([]byte(nil), ebml.UintElement(ebml.IDTrackNumber, 3)...)
	track = append(track, ebml.UintElement(ebml.IDTrackUID, 303)...)
	track = append(track, ebml.UintElement(ebml.IDTrackType, ebml.TrackTypeAudio)...)
	track = append(track, ebml.StringElement(ebml.IDCodecID, "A_MPEG/L3")...)
	entry := ebml.BuildElement(ebml.IDTrackEntry, track)
	buf.Write(ebml.BuildElement(ebml.IDTracks, entry))

	buf.Write(ebml.UnknownHeader(ebml.IDCluster, 8))
	buf.Write(ebml.UintElement(ebml.IDTimecode, 0))
	block := blockPayload(3, 0, 0, []byte{0xff, 0xfb, 0x90, 0x00})
	buf.Write(ebml.BuildElement(ebml.IDSimpleBlock, block))
	return buf.Bytes()
}
